    certificationsDesc: 'கரிம சான்றிதழ்கள், ஹலால் நட்பு விருப்பங்கள் மற்றும் முழுமையான தடமறிதல் ஆவணங்கள் வழங்கப்படுகின்றன.',
    flexibleVolumeModal: 'உங்க மாதாந்திர ஆர்டர் அளவுடன் வளரும் போட்டியான படிநிலை விலையைப் பெறுங்கள். நீங்க அதிகம் ஆர்டர் செய்தால், உங்க சேமிப்பு அதிகம் — வெளிப்படையான மேற்கோள் அடிப்படை விலை, அளவு-லாக் தள்ளுபடிகள் மற்றும் உங்க தேவைகள் மாறும்போது அர்ப்பணிப்பு விலை மதிப்பாய்வு. திரும்பத் திரும்ப ஆர்டர் திட்டமிடும் உணவகங்கள், ஹோட்டல்கள், சில்லறை விற்பனையாளர்கள் மற்றும் நிறுவன வாங்குபவர்களுக்கு ஏற்றது.',
    reliableDeliveryModal: 'உங்க சமையலறை அல்லது கடை செயல்பாடுகளுக்கு ஏற்ற தினசரி, வாராந்திர அல்லது தனிப்பயன் விநியோக சுழற்சியைத் தேர்ந்தெடுங்க. ஒவ்வொரு ஆர்டரும் எங்க குளிர்சாதன லாஜிஸ்டிக்ஸ் வழியாகச் சென்று ஒவ்வொரு முறையும் சரியான நேரத்தில் வந்து சேரும் — உங்க உற்பத்தி எப்போது வரும் என்பதை எப்போதும் அறிய எங்க குழுவின் நேரடி ஒருங்கிணைப்புடன்.',
    invoiceBillingModal: 'உங்க அக்கவுண்ட் குழுவிற்கு 30 நாள் கடன் விதிமுறைகளுடன் வணிக நட்பு பில்லிங். சரியான GST/HSN மற்றும் ஏற்றுமதி ஆவணங்களுடன் ஒருங்கிணைந்த மாதாந்திர இன்வாய்ஸ்களை நாங்கள் வெளியிடுவதால், உங்க வாங்கல்களை ஒப்பிடுவது எளிது மற்றும் முற்றிலும் காகிதமற்றது.',
    accountManagerModal: 'ஒவ்வொரு B2B வாடிக்கையாளருக்கும் அர்ப்பணிப்பு அக்கவுண்ட் மேலாளர் இருப்பார் — உங்க வணிகத்தை உள்ளாட்சியாக அறிந்த ஒரே தொடர்பு புள்ளி. ஆர்டர் ஒருங்கிணைப்பு முதல் மெனு திட்டமிடல் மற்றும் சிக்கல்களை விரைவாகத் தீர்ப்பது வரை, உங்க அக்கவுண்ட் மேலாளர் எல்லாவற்றையும் சீராக நடத்துகிறார்.',
    certificationsModal: 'உங்க சொந்த சான்றிதழ்கள் மற்றும் தணிக்கைகளுக்கு ஆதரவான முழு ஆவணங்கள்: கரிம சான்றிதழ்கள் (NPOP / USDA / EU சமமானவை), ஹலால் நட்பு விருப்பங்கள், முழுமையான பண்ணையிலிருந்து ஏற்றுமதி வரை தடமறிதல், மற்றும் நாங்கள் அனுப்பும் ஒவ்வொரு தொகுதிக்கும் ஆய்வக சோதனை அறிக்கைகள்.',
